head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.key_row = '';
scwin.isur_id = '';
scwin.corp_usr_tp_cd = '';
scwin.contn_id = '';
scwin.contn_grp_id = '';
scwin.ans_obj_contn_id = '';
scwin.noti_obj_sys_tp_cd = '';
scwin.ques_bz_tp_cd = '';
scwin.opn_yn = '';
scwin.reply_yn = '';

//////////////////////////////////////
//////////////////////////////////////

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 패널라운드 처리
        $c.cm.PanelToGroupBox(panel_1);
        scwin.setCode();
        scwin.initPage();
        await scwin.search();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30341.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Reply_onclick
 * @description 「답변」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Reply_onclick = async function() {
    try {
        await scwin.reply();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30341.btn_Reply_onclick" });
    }
};

/**
 * @method
 * @name btn_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30341.btn_Close_onclick" });
    }
};

/**
 * @method
 * @name trs_Save_OnFail
 * @description Save On Fail 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnFail = async function() {
    try {
        await $c.win.alert(trs_Save);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30341.trs_Save_OnFail" });
    }
};

/**
 * @method
 * @name trs_Save_OnSuccess
 * @description Save On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_Save_OnSuccess = async function() {
    try {
        const msg = $c.stf.getMessageParam("MSG-A001", gLastJob);
        await $c.win.alert(msg);
        const fr_fn_Search = $c.frame.path("../").fn_search;
        fr_fn_Search();
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF30341.trs_Save_OnSuccess" });
    }
};

/**
 * @method
 * @name grd_FILE_LIST_OnClick
 * @description grd_FILE_LIST 클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    try {
        scwin.downLoad(row, colid);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF30341.grd_FILE_LIST_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + "ULDSTF30341.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // alert(url);
    const sbmOptions = {
        id : "sbm_dts_MASTER",
        action : "/VocQnA.do",
        ref : "",
        target : "dts_MASTER=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    url += "&CONTN_ID=" + scwin.contn_id;
    url += "&CONTN_GRP_ID=" + scwin.contn_grp_id;
    url += "&ANS_OBJ_CONTN_ID=" + scwin.ans_obj_contn_id;
    url += "&NOTI_OBJ_SYS_TP_CD=" + scwin.noti_obj_sys_tp_cd;
    url += "&SCREN_ID=" + "ULDSTF30341.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    const sbmOptions2 = {
        id : "sbm_dts_FILE_LIST",
        action : "/VocQnA.do",
        ref : "",
        target : "dts_FILE_LIST=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    // TODO Stage2: sbmRtn2 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name initPage
 * @description init Page 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPage = function() {
    txb_REPLY_YN.hide();
    // showObj(btn_Delete, false);
    if (scwin.reply_yn === 'Y') {
        // 미답변상태
        btn_Reply.hide();
    }
};

/**
 * @method
 * @name setCode
 * @description set Code 처리
 * @returns {void}
 * @hidden N
 */
scwin.setCode = function() {
    scwin.key_row = frame.opener.scwin.key_row;
    scwin.isur_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ISUR_CD");
    scwin.corp_usr_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CORP_USR_TP_CD");
    scwin.contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_ID");
    scwin.contn_grp_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "CONTN_GRP_ID");
    scwin.ans_obj_contn_id = frame.opener.dts_qnaList.getCellData(scwin.key_row, "ANS_OBJ_CONTN_ID");
    scwin.noti_obj_sys_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "NOTI_OBJ_SYS_TP_CD");
    scwin.ques_bz_tp_cd = frame.opener.dts_qnaList.getCellData(scwin.key_row, "QUES_BZ_TP_CD");
    scwin.opn_yn = frame.opener.dts_qnaList.getCellData(scwin.key_row, "OPN_YN");
    scwin.reply_yn = frame.opener.dts_qnaList.getCellData(scwin.key_row, "REPLY_YN");
    // alert("contn_id : " + contn_id + " : contn_grp_id : " + contn_grp_id + " : ans_obj_contn_id : " + ans_obj_contn_id + " : noti_obj_sys_tp_cd : " + noti_obj_sys_tp_cd);
    // alert("opn_yn : " + opn_yn + " : reply_yn : " + reply_yn);

};

/**
 * @method
 * @name downLoad
 * @description down Load 처리
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {void}
 * @hidden N
 */
scwin.downLoad = function(row, colid) {
    const filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename === "") return;
    if (colid === "ATTACH_FILE_NM") {
        const vCONTN_ID = dts_FILE_LIST.getCellData(row, "CONTN_ID");
        const vCONTN_GRP_ID = dts_FILE_LIST.getCellData(row, "CONTN_GRP_ID");
        const vANS_OBJ_CONTN_ID = dts_FILE_LIST.getCellData(row, "ANS_OBJ_CONTN_ID");
        const vNOTI_OBJ_SYS_TP_CD = dts_FILE_LIST.getCellData(row, "NOTI_OBJ_SYS_TP_CD");
        const vCONTN_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "CONTN_ATTACH_SEQ");
        let url = "/filedownload.do?gubun=20";
        url += "&contn_id=" + vCONTN_ID;
        url += "&contn_grp_id=" + vCONTN_GRP_ID;
        url += "&ans_obj_contn_id=" + vANS_OBJ_CONTN_ID;
        url += "&noti_obj_sys_tp_cd=" + vNOTI_OBJ_SYS_TP_CD;
        url += "&contn_attach_seq=" + vCONTN_ATTACH_SEQ;
        // alert(url);
        // location.href = "/filedownload.do?file_id=" + vCONTN_ID + "&attach_seq=" + vCONTN_ATTACH_SEQ + "&gubun=16";
        location.href = url;
    }
};

/**
 * @method
 * @name reply
 * @description reply 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.reply = async function() {
    const options = {
        id: "ULDSTF30342",
        title: "고객의소리 Q&A 답변",
        type: "browserPopup",
        width: "600px",
        height: 460 + 30,
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("/bizspt/ULDSTF30342.gfm", options);
};
